/**
 * Custom Worker entry. Serves already-rendered card images straight from KV, so a cached image costs
 * a few microseconds of CPU instead of booting Next.js (the free plan allows ~10ms per request).
 * Everything else goes to the OpenNext handler.
 */
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type KV = { get(key: string, type: "arrayBuffer"): Promise<ArrayBuffer | null> };
type Env = { IMAGES?: KV } & Record<string, unknown>;

const IMAGE_ROUTE = /^\/api\/card\/([A-Za-z0-9-]{1,39})\/image$/;

export default {
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    if (request.method === "GET" && env.IMAGES) {
      const url = new URL(request.url);
      const m = url.pathname.match(IMAGE_ROUTE);
      if (m) {
        const f = url.searchParams.get("format");
        const format = f === "og" || f === "sheet" ? f : "card";
        const png = await env.IMAGES.get(`${format}:${m[1].toLowerCase()}`, "arrayBuffer");
        if (png) {
          return new Response(png, {
            headers: {
              "Content-Type": "image/png",
              "Cache-Control": "public, max-age=3600, s-maxage=21600",
              "X-Specsheet-Image": "kv",
            },
          });
        }
      }
    }
    return handler.fetch(request, env, ctx);
  },
};
